raw:
{
  "items": [
    {
      "id": "parent_access",
      "status": "covered",
      "handbook_quote": "Visit the center any time we are open, without advance notice, to observe your child, activities, the building, the grounds, and equipment;"
    },
    {
      "id": "liability_insurance_notice",
      "status": "covered",
      "handbook_quote": "We carry liability insurance of $300,000 per occurrence, as Texas requires. If that ever changes, we will tell every family in writing within 14 days."
    },
    {
      "id": "operational_policies_minimum",
      "status": "covered",
      "handbook_quote": "Welcome to Prickly Pear Meadow Learning Center! We are a licensed Texas child-care center for children from 6 weeks through 5 years old."
    },
    {
      "id": "policy_hours_release",
      "status": "covered",
      "handbook_quote": "We are open Monday through Friday, 6:30 a.m. to 6:30 p.m., twelve months a year. We close for New Year's Day, Memorial Day, Independence Day, Labor Day, Thanksgiving Day and the day after, Christmas Eve, and Christmas Day."
    },
    {
      "id": "policy_illness_medication",
      "status": "covered",
      "handbook_quote": "Before we give any medicine, simply tell your child's teacher at drop-off what to give and when; your verbal okay covers the full course of treatment."
    },
    {
      "id": "policy_medical_emergencies_notifications",
      "status": "covered",
      "handbook_quote": "If a child needs immediate medical treatment, we will call 911, give first aid or CPR, call you, contact your child's physician if needed, and keep the other children supervised."
    },
    {
      "id": "policy_discipline_guidance",
      "status": "covered",
      "handbook_quote": "Discipline at Prickly Pear Meadow is individualized, consistent, matched to each child's understanding, and aimed at teaching self-control."
    },
    {
      "id": "policy_safe_sleep",
      "status": "missing",
      "handbook_quote": "",
      "handbook_page": null,
      "rule_quote": "",
      "rule_section": "",
      "explanation": "The handbook does not include a safe sleep policy for infants from birth through 12 months old.",
      "fix": "Our safe sleep policy for infants from birth through 12 months old follows Texas minimum standards: infants are placed on their backs to sleep in their own cribs, with no swaddling, head covering, or loose bedding unless a health-care professional documents a medical need."
    },
    {
      "id": "policy_hearing_vision_enrollment",
      "status": "covered",
      "handbook_quote": "Enrollment begins with a tour and a conversation with the director. On or before your child's first day, you will sign our enrollment agreement, which includes these policies, and complete the admission form."
    },
    {
      "id": "policy_transportation_water",
      "status": "covered",
      "handbook_quote": "We do not provide transportation, swimming, or water play activities, and we do not keep pets or animals at the center."
    },
    {
      "id": "policy_field_trips_animals",
      "status": "covered",
      "handbook_quote": "Older children take occasional walking field trips to the library or the park, with your signed permission."
    },
    {
      "id": "policy_physical_activity",
      "status": "covered",
      "handbook_quote": "We offer at least two outdoor play times every day, weather permitting."
    },
    {
      "id": "policy_insect_sunscreen",
      "status": "missing",
      "handbook_quote": "",
      "handbook_page": null,
      "rule_quote": "",
      "rule_section": "",
      "explanation": "The handbook does not state procedures for providing and applying insect repellant and sunscreen.",
      "fix": "If insect repellant or sunscreen is used, we will follow the product directions and our written procedures for when and how it is applied, and we will tell families which products we use."
    },
    {
      "id": "policy_parent_rights",
      "status": "covered",
      "handbook_quote": "As a parent, you have the right to:"
    },
    {
      "id": "policy_review_concerns",
      "status": "missing",
      "handbook_quote": "",
      "handbook_page": null,
      "rule_quote": "",
      "rule_section": "",
      "explanation": "The handbook does not state procedures for parents to review and discuss questions or concerns with the director.",
      "fix": "If you have questions or concerns about our policies or procedures, please schedule a time to review and discuss them with the child-care center director."
    },
    {
      "id": "children_records_accessible",
      "status": "covered",
      "handbook_quote": "Children's records are immediately available to your child's caregivers during all hours of operation in case of emergency."
    },
    {
      "id": "abuse_neglect_reporting",
      "status": "conflict",
      "handbook_quote": "Every staff member who suspects abuse, neglect, or exploitation must report it to the director, who will decide whether to call the Texas Abuse and Neglect Hotline.",
      "handbook_page": 4,
      "rule_quote": "Reporting and ensuring your employees and volunteers report suspected abuse, neglect, or exploitation directly to the Texas Abuse and Neglect Hotline, as required by Texas Family Code §261.10; an employee may not delegate the responsibility to make a report, and you may not require an employee to seek approval to file a report or notify you that a report was made",
      "rule_section": "§746.201. What are my responsibilities as the permit holder?",
      "explanation": "The handbook requires staff to report suspected abuse or neglect to the director for approval instead of reporting directly to the Texas Abuse and Neglect Hotline.",
      "fix": "Any staff member who suspects abuse, neglect, or exploitation must report it directly to the Texas Abuse and Neglect Hotline; the director can help, but cannot require approval before a report is made."
    },
    {
      "id": "classroom_ratio_chart",
      "status": "conflict",
      "handbook_quote": "Each infant teacher cares for up to six babies, and our infant room holds up to twelve babies when we are full.",
      "handbook_page": 1,
      "rule_quote": "If the specified age of the children in the group is… Then the maximum number of children one caregiver may supervise is… 0 – 11 months 4",
      "rule_section": "§746.1601. How many children may one caregiver supervise?",
      "explanation": "The handbook allows one caregiver to supervise up to six infants, while the rule allows a maximum of four infants per caregiver.",
      "fix": "We follow Texas child-to-caregiver ratios at all times, including a maximum of four infants per caregiver and a maximum infant group size of ten."
    },
    {
      "id": "infant_back_sleep",
      "status": "not_mentioned"
    },
    {
      "id": "prohibited_discipline",
      "status": "conflict",
      "handbook_quote": "Children who refuse to help clean up may miss that afternoon's snack.",
      "handbook_page": 2,
      "rule_quote": "Punishment associated with food, naps, or toilet training [High];",
      "rule_section": "§746.2805. What types of discipline and guidance or punishment are prohibited?",
      "explanation": "The handbook withholds a snack as a consequence for behavior, which the rule prohibits.",
      "fix": "We never use food, naps, or toilet training as a consequence for behavior; if a child needs help cleaning up, a teacher will guide and support the child."
    },
    {
      "id": "field_trip_parent_notice",
      "status": "conflict",
      "handbook_quote": "We post a notice at the front desk on the morning of each field trip, showing where we are going, when we will leave, and when we expect to return.",
      "handbook_page": 4,
      "rule_quote": "The notice must be posted at least 48 hours in advance of a field trip.",
      "rule_section": "§746.3003. Must I notify parents before I take children away from the child-care center on a field trip?",
      "explanation": "The handbook posts field trip notice on the morning of the trip instead of at least 48 hours in advance.",
      "fix": "We post field trip notice at least 48 hours before the trip in a prominent place, showing where children are going, when they will leave, and when they are expected to return."
    },
    {
      "id": "cacfp_meal_patterns",
      "status": "covered",
      "handbook_quote": "We serve breakfast, lunch, and snacks that follow the USDA Child and Adult Care Food Program meal patterns."
    },
    {
      "id": "ill_child_exclusion",
      "status": "covered",
      "handbook_quote": "We are not licensed for get-well care, so children must stay home, or will be sent home, when:"
    },
    {
      "id": "medication_authorization",
      "status": "conflict",
      "handbook_quote": "Before we give any medicine, simply tell your child's teacher at drop-off what to give and when; your verbal okay covers the full course of treatment.",
      "handbook_page": 3,
      "rule_quote": "Authorization to administer medication to a child in your care must be obtained from the child’s parent: (1) In writing, signed and dated; (2) In an electronic format that is capable of being viewed and saved; or (3) By telephone to administer a single dose of a medication.",
      "rule_section": "§746.3803. What authorization must I obtain before administering a medication to a child in my care?",
      "explanation": "The handbook accepts verbal authorization for a full course of medication, while the rule requires written, electronic, or telephone authorization for a single dose.",
      "fix": "Before giving medicine, we need your authorization in writing, in an electronic format we can view and save, or by phone for a single dose; authorizations expire one year after they are given."
    },
    {
      "id": "food_allergy_emergency_plan",
      "status": "covered",
      "handbook_quote": "If your child has a food allergy diagnosed by a health-care professional, we need a food allergy emergency plan signed and dated by your child's health-care professional and by you before your child's first day."
    },
    {
      "id": "release_only_authorized",
      "status": "covered",
      "handbook_quote": "We release children only to a parent or to an adult the parent has listed in writing on the authorized pick-up list."
    },
    {
      "id": "monthly_fire_drill",
      "status": "covered",
      "handbook_quote": "We practice a fire drill every month and are able to get all children outside within three minutes."
    }
  ],
  "extra_conflicts": [],
  "summary": "The handbook covers most required policies and rules, but it conflicts with Texas rules on abuse reporting, infant ratios, food-related discipline, field trip notice, and medication authorization. It also omits required safe sleep, insect repellant and sunscreen, and parent review procedures."
}
